import heapq


def cheapest_drive(price: list[int], roads: list[list[int]], capacity: int, src: int, dst: int) -> int:
    adj = [[] for _ in price]
    for a, b, d in roads:
        adj[a].append((b, d))
        adj[b].append((a, d))
    spent = {(src, 0): 0}                # least money to be in a city with that much fuel
    heap = [(0, src, 0)]                 # (money spent, city, fuel in tank)
    while heap:
        cost, city, fuel = heapq.heappop(heap)
        if city == dst:
            return cost                  # first pop of dst, with any fuel left, is optimal
        if cost > spent[(city, fuel)]:
            continue                     # stale entry
        moves = [(cost, nxt, fuel - d) for nxt, d in adj[city] if d <= fuel]  # drive: free
        if fuel < capacity:
            moves.append((cost + price[city], city, fuel + 1))               # buy one unit
        for c, v, f in moves:
            if c < spent.get((v, f), float("inf")):
                spent[(v, f)] = c
                heapq.heappush(heap, (c, v, f))
    return -1
